"% Steady level-flight trim — transport aircraft
% Solves lift = weight and drag = thrust for alpha and thrust

% --- Inputs ---
W       = 280000.0;     % lbf
S       = 2730.0;       % ft^2
h       = 35000.0;      % ft
V       = 780.0;        % ft/s

CL0     = 0.18;         % lift-curve zero-alpha intercept
CLalpha = 5.6;          % per rad
CD0     = 0.019;        % parasitic drag coefficient
k       = 0.045;        % induced-drag factor

rho0    = 0.0023769;    % slug/ft^3 (sea-level)
T0      = 68000.0;      % lbf at V0
V0      = 780.0;        % ft/s

% --- Atmosphere / dynamic pressure ---
rho  = rho0 * exp(-h/23800);
qbar = 0.5 * rho * V^2;

% --- Trim solve ---
% Lift  = Weight  ->  qbar * S * (CL0 + CLalpha*alpha) = W
CL_trim      = W / (qbar * S);
alpha_rad    = (CL_trim - CL0) / CLalpha;
alpha_deg    = alpha_rad * 180/pi;

% Drag = Thrust
CD_trim      = CD0 + k * CL_trim^2;
thrust_lbf   = qbar * S * CD_trim;

% --- Sanity: required throttle (informational only) ---
delta_t = thrust_lbf / (T0 * (V/V0)^0.8);

% --- Write result.json ---
result = struct( ...
    'alpha_trim_deg', alpha_deg, ...
    'thrust_lbf',     thrust_lbf );

fid = fopen('result.json', 'w');
fwrite(fid, jsonencode(result));
fclose(fid);"
